import { spawn } from "node:child_process";

/** The URL is generated by the OAuth service, never supplied by an HTTP caller. */
export async function openAuthorizationBrowser(url: string): Promise<boolean> {
  if (!url.startsWith("https://accounts.google.com/o/oauth2/v2/auth?")) return false;
  const [command, args] = process.platform === "win32"
    ? ["rundll32.exe", ["url.dll,FileProtocolHandler", url]] as const
    : process.platform === "darwin" ? ["open", [url]] as const : ["xdg-open", [url]] as const;
  return new Promise(resolve => {
    const child = spawn(command, [...args], { windowsHide: true, stdio: "ignore" });
    const timeout = setTimeout(() => { child.kill(); resolve(false); }, 8000);
    child.once("error", () => { clearTimeout(timeout); resolve(false); });
    child.once("close", code => { clearTimeout(timeout); resolve(code === 0); });
  });
}
